    [('spec={}', 'strategy: None 时,用 v1beta1 写入的 replicas=3 存进 etcd 之后剩下的内容'), ('1 / 0', '只写不读时 webhook 的调用次数 / v1beta1 list 6 个对象时的调用次数'), ('["v1","v1beta1"]', '把存储版本改到 v1beta1 之后的 status.storedVersions')],
